// ============================================================
// ROBOT CONNECTION STATUS
//
// Input:
// {
//   "status": "READY",
//   "message": "Robot control connected",
//   "connected": true
// }
//
// Stores:
// global.robot_Data.connection
//
// Output:
// connected    → "Robot is in Command Mode"
// disconnected → "Robot in Listen Mode"
// ============================================================

let data = msg.payload;

// API response may arrive as a JSON string
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    }
    catch (err) {
        node.error("Invalid robot connection JSON", msg);
        return null;
    }
}

if (!data || typeof data.connected !== "boolean") {
    node.error("Robot connection status not found", msg);
    return null;
}


// ============================================================
// GET EXISTING ROBOT MEMORY
// ============================================================

let robot_Data = global.get("robot_Data") || {};


// ============================================================
// STORE ROBOT CONNECTION STATUS
// ============================================================

robot_Data.connection = {
    status: data.status || "UNKNOWN",
    message: data.message || "",
    connected: data.connected
};


// Save memory
global.set("robot_Data", robot_Data);


// ============================================================
// SAM OUTPUT
// ============================================================

msg.topic = "ROBOT_CONNECTION_STATUS";

if (data.connected === true) {

    msg.payload = "Robot is in Command Mode";

}
else {

    msg.payload = "Robot in Listen Mode";

}

return msg;

// ============================================================
// SAM RESPONSE
//
// Receives recognized responses from:
//     Parser 1
//     Parser 2
//     Parser 3
//     Parser 4
//     Parser 5
//
// Also handles:
//
//     FINAL_PRODUCTION_SPEED
//
// FINAL_PRODUCTION_SPEED:
//     payload = numeric production speed
//     ttsText = voice response
//
// ============================================================


// ============================================================
// 1. ACCEPT VALID RESPONSE TYPES
// ============================================================

if (
    msg.topic !== "SAM_RESPONSE" &&
    msg.topic !== "FINAL_PRODUCTION_SPEED"
) {
    return null;
}


// ============================================================
// 2. SPECIAL CASE:
//    FINAL PRODUCTION SPEED
//
// IMPORTANT:
//    Do NOT treat msg.payload as the TTS text.
//
//    msg.payload = numeric value for PLC
//
//    Example:
//        msg.payload = 70
//
//    TTS uses:
//        msg.ttsText
// ============================================================

if (
    msg.topic === "FINAL_PRODUCTION_SPEED"
) {

    // --------------------------------------------------------
    // Validate final speed
    // --------------------------------------------------------

    let finalSpeed =
        Number(msg.payload);

    if (!Number.isFinite(finalSpeed)) {

        node.error(
            "SAM RESPONSE | Invalid FINAL_PRODUCTION_SPEED"
        );

        return null;
    }


    // --------------------------------------------------------
    // TTS TEXT
    // --------------------------------------------------------

    let ttsText =
        "";

    if (
        msg.ttsText !== undefined &&
        msg.ttsText !== null &&
        String(msg.ttsText).trim() !== ""
    ) {

        ttsText =
            String(msg.ttsText).trim();

    }
    else {

        ttsText =
            "Got it. I will increase the production speed to " +
            finalSpeed +
            " percent, provided the process remains stable.";
    }


    // --------------------------------------------------------
    // SAM RESPONSE
    // --------------------------------------------------------

    msg.samResponse =
        ttsText;


    // --------------------------------------------------------
    // IMPORTANT:
    // For SAM Voice Output, payload becomes TTS text.
    //
    // The PLC branch receives the original message
    // separately before this node.
    // --------------------------------------------------------

    msg.payload =
        ttsText;

    msg.topic =
        "SAM_RESPONSE";


    // --------------------------------------------------------
    // SESSION CONTROL
    // --------------------------------------------------------

    msg.samSessionActive =
        true;

    msg.samSessionEnded =
        false;

    msg.samListenAfterTTS =
        true;


    // --------------------------------------------------------
    // MARK TTS TYPE
    // --------------------------------------------------------

    msg.samTTS =
        true;

    msg.samTTSFinishedAction =
        "LISTEN";


    // --------------------------------------------------------
    // DEBUG
    // --------------------------------------------------------

    node.warn(
        "======================================"
    );

    node.warn(
        "SAM RESPONSE | FINAL SPEED"
    );

    node.warn(
        "SAM RESPONSE | FINAL SPEED = " +
        finalSpeed +
        "%"
    );

    node.warn(
        "SAM RESPONSE | TTS = " +
        ttsText
    );

    node.warn(
        "SAM RESPONSE | SESSION ACTIVE = TRUE"
    );

    node.warn(
        "SAM RESPONSE | LISTEN AFTER TTS = TRUE"
    );

    node.warn(
        "======================================"
    );


    return msg;
}


// ============================================================
// 3. NORMAL SAM RESPONSE
// ============================================================

if (
    msg.payload === undefined ||
    msg.payload === null ||
    msg.payload === ""
) {
    return null;
}


const response =
    String(msg.payload).trim();


if (response === "") {
    return null;
}


let samData =
    global.get("SAM_data") || {};


// ============================================================
// 4. COMMAND TRACKER COMPLETION
//
// Do NOT mark the command as recognized if this message
// was generated by the Unknown Command Manager.
// ============================================================

let tracker =
    global.get("SAM_Command_Tracker");


if (
    tracker &&
    msg.samCommandId === tracker.commandId &&
    msg.samUnknownCommand !== true
) {

    tracker.recognized = true;
    tracker.completed = true;
    tracker.waiting = false;
    tracker.unknown = false;
    tracker.responseTime = Date.now();


    global.set(
        "SAM_Command_Tracker",
        tracker
    );


    node.warn(
        "SAM COMMAND TRACKER | COMMAND RECOGNIZED"
    );

    node.warn(
        "COMMAND ID: " +
        tracker.commandId
    );

    node.warn(
        "RESPONSE: " +
        response
    );
}


// ============================================================
// 5. NORMAL RESPONSE PROCESSING
// ============================================================

msg.topic =
    "SAM_RESPONSE";

msg.payload =
    response;

msg.samResponse =
    response;


// ============================================================
// 6. SESSION STATE
// ============================================================

msg.samSessionActive =
    samData.samActive === true;


// ============================================================
// 7. WAKE ACCEPTED
// ============================================================

if (
    samData.samActive === true &&
    (
        response.indexOf("Hello Mr.") === 0 ||
        response.indexOf("Hello I am Sam AI") === 0
    )
) {

    msg.samWakeAccepted =
        true;

}
else {

    msg.samWakeAccepted =
        false;
}


// ============================================================
// 8. SESSION ENDED
// ============================================================

if (
    samData.samActive !== true
) {

    msg.samSessionEnded =
        true;

}
else {

    msg.samSessionEnded =
        false;
}


// ============================================================
// 9. TTS
// ============================================================

msg.ttsText =
    response;

msg.samTTS =
    true;


// ============================================================
// 10. DEBUG
// ============================================================

node.warn(
    "SAM RESPONSE → VOICE: " +
    response
);

node.warn(
    "SAM SESSION STATE → " +
    msg.samSessionActive
);


// ============================================================
// 11. OUTPUT
// ============================================================

return msg;

// ============================================================
// SAM WAKE WORD GATE
//
// OUTPUT 1 → SAM RESPONSE
// OUTPUT 2 → CONNECT / DISCONNECT
// OUTPUT 3 → ROBOT INFORMATION
// OUTPUT 4 → JOINT COMMAND
// OUTPUT 5 → HOME
// OUTPUT 6 → UNUSED
// ============================================================


let input = "";


// ============================================================
// READ INPUT
// ============================================================

if (typeof msg.payload === "string") {
    input = msg.payload.trim();
}
else if (
    msg.payload !== undefined &&
    msg.payload !== null
) {
    input = String(msg.payload).trim();
}

if (!input) {
    return [null, null, null, null, null, null];
}


// ============================================================
// CLEAN INPUT
// ============================================================

let clean = input
    .toLowerCase()

    // Normalize spoken/Unicode minus characters
    .replace(/[−–—]/g, "-")

    .replace(/[.,!?;:]/g, " ")
    .replace(/\s+/g, " ")
    .trim();


// ============================================================
// LOAD SAM STATE
// ============================================================

let samData = global.get("SAM_data") || {};

let samActive =
    samData.samActive === true;

let savedName =
    global.get("SAM_userName") || "";

let waitingForName =
    global.get("SAM_waitingForName") === true;


// ============================================================
// STEP 1
// WAKE WORD = "SAM"
// ============================================================

if (
    !samActive &&
    !waitingForName &&
    clean === "sam"
) {

    // --------------------------------------------------------
    // NAME ALREADY REMEMBERED
    // --------------------------------------------------------

    if (savedName !== "") {

        samData.samActive = true;

        global.set(
            "SAM_data",
            samData
        );

        return [
            {
                topic: "SAM_RESPONSE",
                payload:
                    "Hello Mr " +
                    savedName +
                    ", how can I help you?",
                samSessionActive: true,
                samSessionEnded: false
            },
            null,
            null,
            null,
            null,
            null
        ];
    }


    // --------------------------------------------------------
    // NO NAME REMEMBERED
    // --------------------------------------------------------

    samData.samActive = true;

    global.set(
        "SAM_data",
        samData
    );

    global.set(
        "SAM_waitingForName",
        true
    );

    return [
        {
            topic: "SAM_RESPONSE",
            payload:
                "Hello I am Sam AI, Your Robot assistant. Who are you?",
            samSessionActive: true,
            samSessionEnded: false
        },
        null,
        null,
        null,
        null,
        null
    ];
}


// ============================================================
// STEP 2
// WAITING FOR USER NAME
// ============================================================

if (waitingForName) {

    let name = "";

    let match1 =
        clean.match(/^i am\s+(.+)$/i);

    let match2 =
        clean.match(/^my name is\s+(.+)$/i);


    if (match1) {
        name = match1[1].trim();
    }
    else if (match2) {
        name = match2[1].trim();
    }
    else {
        name = input.trim();
    }


    name = name
        .replace(/[.,!?;:]/g, "")
        .trim();


    if (name !== "") {

        global.set(
            "SAM_userName",
            name
        );

        global.set(
            "SAM_waitingForName",
            false
        );

        samData.samActive = true;

        global.set(
            "SAM_data",
            samData
        );

        return [
            {
                topic: "SAM_RESPONSE",
                payload:
                    "Hello Mr " +
                    name +
                    ", I will remember your name. How can I help you?",
                samSessionActive: true,
                samSessionEnded: false
            },
            null,
            null,
            null,
            null,
            null
        ];
    }
}


// ============================================================
// STEP 3
// SAM GATE IS OPEN
// ============================================================

if (samActive) {


    // ========================================================
    // EXIT NAME
    // ========================================================

    if (
        clean === "exit name" ||
        clean === "exit"
    ) {

        let goodbyeName =
            savedName !== ""
                ? savedName
                : "Sir";

        samData.samActive = false;

        global.set(
            "SAM_data",
            samData
        );

        global.set(
            "SAM_userName",
            ""
        );

        global.set(
            "SAM_waitingForName",
            false
        );

        return [
            {
                topic: "SAM_RESPONSE",
                payload:
                    "Ok Mr " +
                    goodbyeName +
                    ", it was nice talking to you.",
                samSessionActive: false,
                samSessionEnded: true
            },
            null,
            null,
            null,
            null,
            null
        ];
    }


    // ========================================================
    // THANK YOU
    // ========================================================

    if (
        clean === "thank you" ||
        clean === "thanks" ||
        clean === "thankyou"
    ) {

        samData.samActive = false;

        global.set(
            "SAM_data",
            samData
        );

        return [
            {
                topic: "SAM_RESPONSE",
                payload: "You're welcome.",
                samSessionActive: false,
                samSessionEnded: true
            },
            null,
            null,
            null,
            null,
            null
        ];
    }


    // ========================================================
    // CONNECT / DISCONNECT → OUTPUT 2
    // ========================================================

    if (
        clean === "connect" ||
        clean === "connect robot" ||
        clean === "disconnect" ||
        clean === "disconnect robot"
    ) {

        return [
            null,
            msg,
            null,
            null,
            null,
            null
        ];
    }

    // ============================================================
    // JOINT COMMAND DETECTION
    //
    // FLEXIBLE FORMATS:
    //
    //   J1 + 10
    //   J1 - 10
    //   J1 plus 10
    //   J1 minus 10
    //
    //   Joint 1 + 10
    //   Joint 1 - 10
    //   Joint 1 plus 10
    //   Joint 1 minus 10
    //
    //   Joint 2 + 50
    //   Joint 2 - 50
    //
    //   joint 1  -10
    //   joint 2 +50
    //
    // ============================================================

    let jointCommand = clean.match(
        /^(?:j|joint)\s*[1-6]\s+(?:(?:plus|minus)\s+\d+(?:\.\d+)?|[+-]\s*\d+(?:\.\d+)?)\s*(?:deg|degree|degrees)?$/
    );

    if (jointCommand) {

        node.warn(
            "SAM JOINT COMMAND → OUTPUT 4: " + input
        );

        return [
            null,   // Output 1 → SAM Response
            null,   // Output 2 → Connect / Disconnect
            null,   // Output 3 → Robot Information
            msg,    // Output 4 → Joint Command
            null,   // Output 5 → Home
            null    // Output 6
        ];
    }
    // ========================================================
    // HOME COMMAND → OUTPUT 5
    // ========================================================

    if (
        clean === "home" ||
        clean === "go home" ||
        clean === "robot home"
    ) {

        return [
            null,
            null,
            null,
            null,
            msg,
            null
        ];
    }


    // ========================================================
    // ALL OTHER COMMANDS → OUTPUT 3
    // ROBOT INFORMATION
    // ========================================================

    return [
        null,
        null,
        msg,
        null,
        null,
        null
    ];
}


// ============================================================
// STEP 4
// GATE CLOSED
// ============================================================

return [
    {
        topic: "SAM_RESPONSE",
        payload:
            "Please say the wake word.",
        samSessionActive: false,
        samSessionEnded: true
    },
    null,
    null,
    null,
    null,
    null
];

// ============================================================
// SAM ROBOT CONNECT / DISCONNECT
//
// OUTPUT:
//     true  = CONNECT
//     false = DISCONNECT
// ============================================================

let input = "";

if (typeof msg.payload === "string") {
